 * @tparam R Right operand type
 */
template <typename Op, typename L, typename R>
    requires HasReactOp<L, R>
constexpr auto make_binary_op(L &&l, R &&r) {
    return make_binary_expr<Op>(std::forward<L>(l), std::forward<R>(r));
}

