    React &operator/=(const U &rhs) {
        atomicDivideAssign(*getPtr(), rhs);
        return *this;
    }

    /// @brief Compound modulo assignment operator (%=)
    template <typename U>
        requires(IsVarExpr<Expr> && !ConstType<Type> && ModuloAssignable<Type, U>)
    React &operator%=(const U &rhs) {
        atomicModuloAssign(*getPtr(), rhs);
        return *this;
    }

