        : ReactionException(
              "Detected self-observation: node '" + nodeName + "' cannot observe itself",
              ErrorCode::SELF_OBSERVATION, file, line, function),
          m_nodeName(nodeName) {
    }

    const std::string &getNodeName() const noexcept { return m_nodeName; }

private:
    std::string m_nodeName;
};

/**
