/**
 * Function: Test transactional observer updates
 *
 * @param nodeName Name for the node to update
 * @return bool Whether transactional update succeeded (no cycle created)
 */
bool test_transactional_update(const std::string& nodeName) {
    using namespace reaction;

    // 1. Create observer nodes
    auto target = std::make_shared<TestTransactionalObserver>(nodeName + "_target");
    auto dep1   = std::make_shared<TestTransactionalObserver>(nodeName + "_dep1");
    auto dep2   = std::make_shared<TestTransactionalObserver>(nodeName + "_dep2");

    // 2. Get observer graph instance
    auto &graph = ObserverGraph::getInstance();

    // Ensure nodes are known to the graph (optional but explicit)
    graph.addNode(target);
    graph.addNode(dep1);
    graph.addNode(dep2);

    // 3. Set up initial relationship:
    //    target observes dep1 (i.e., dep1 -> target edge in graph terms)
    graph.addObserver(target, dep1);

    // 4. Notify target and verify relationship works
    dep1->reset();
    target->reset();

    dep1->valueChanged(true);  // should propagate to target

    if (!target->wasChanged() || target->getCallCount() != 1) {
        return false;
    }

    // 5. Reset observer for next test
    dep1->reset();
    dep2->reset();
    target->reset();

    // 6. Attempt transactional update that would create cycle
    //    We'll try to make a 2‑cycle:
    //      - currently: target observes dep1
    //      - we add:     dep1 observes target
    //    which should trigger DependencyCycleException.
    bool cycleCaught = false;
    try {
        graph.addObserver(dep1, target); // should throw
    } catch (const DependencyCycleException &) {
        cycleCaught = true;
    } catch (...) {
        // Any other exception is a failure
        return false;
    }

    if (!cycleCaught) {
        // If no cycle exception was thrown, test fails
        return false;
    }

    // 7. Cycle exception has been caught, graph should remain consistent.
    //    Original relationship (target observes dep1) must still hold.

    // 8. Notify target again via dep1
    dep1->valueChanged(true);

    // 9. Verify original relationship is preserved
    //    Target should have been notified exactly once more.
    if (!target->wasChanged() || target->getCallCount() != 1) {
        return false;
    }

    // 10. Return success status
    return true;
}

