/**
 * Function: Test multiple observers watching a single target
 *
 * @param targetName Name for the target node
 * @param observerNames Vector of names for observer nodes
 * @return std::pair<int, bool> Pair of total call count and whether all observers were notified
 */
std::pair<int, bool> test_multiple_observers(const std::string& targetName,
                                             const std::vector<std::string>& observerNames) {
    using reaction::ObserverGraph;
    using reaction::ObserverNode;
    using reaction::NodePtr;

    // 1. Create target node
    auto target = std::make_shared<TestMultipleObserver>(targetName);

    // Register target in the observer graph and optionally set a name
    ObserverGraph::getInstance().addNode(target);
    ObserverGraph::getInstance().setName(target, targetName);

    // 2. Create observer nodes
    std::vector<std::shared_ptr<TestMultipleObserver>> observers;
    observers.reserve(observerNames.size());
    for (const auto& name : observerNames) {
        auto ob = std::make_shared<TestMultipleObserver>(name);
        observers.push_back(ob);

        // Register observer node and give it a name
        ObserverGraph::getInstance().addNode(ob);
        ObserverGraph::getInstance().setName(ob, name);
    }

    // 3. Get observer graph instance (already used above, kept for clarity)
    auto& graph = ObserverGraph::getInstance();
    (void)graph; // suppress unused variable warning if not otherwise referenced

    // 4. Add all observers to watch target
    for (auto& ob : observers) {
        graph.addObserver(ob, target);
    }

    // 5. Notify target
    target->notify(true);

    // 6. Count notifications and verify all observers were notified
    int totalCallCount = 0;
    bool allNotified = true;

    for (auto& ob : observers) {
        int calls = ob->getCallCount();
        totalCallCount += calls;

        if (calls <= 0 || !ob->wasChanged()) {
            allNotified = false;
        }
    }

    // 7. Return total call count and notification status
    return {totalCallCount, allNotified};
}

}  // namespace test_reaction
