                    if (m_observerList.contains(locked_dep)) {
                        ConditionalUniqueLock<ConditionalSharedMutex> observerLock(locked_dep->m_observersMutex);
                        m_observerList.at(locked_dep).get().erase(node);
                    }
                }
            }
            m_dependentList.at(node).clear();
