inline BatchLifecycleResult test_batch_manual_lifecycle(int initialValue, int updatedValue) {
    using namespace reaction;

    // 1. Create reactive variable
    auto v = var(initialValue);

    // 2. Create variable to track recomputation count
    int recomputeCount = 0;

    // 3. Create calculation depending on v
    auto c = calc([&]() {
        ++recomputeCount;
        return v() * 2;
    });

    // Ensure initial evaluation happens
    (void)c.get();

    // 4. Create Batch object that mutates v
    Batch batch([&]() {
        // This write is captured in the batch
        v.value(updatedValue);
    });

    // 5. Check if batch is closed initially
    bool closedInitially = batch.isClosed();

    // 6. Execute batch
    batch.execute();

    // Force evaluation so the calc recomputes if needed
    (void)c.get();

    // 7. Record recompute count after execute
    int recomputeCountAfterExecute = recomputeCount;

    // 8. Close batch
    batch.close();

    // 9. Check if batch is closed after close
    bool closedAfterClose = batch.isClosed();

    // 10. Ensure calculation is evaluated (already done above)
    (void)c.get();

    // 11. Return batch lifecycle result
    return BatchLifecycleResult{
        closedInitially,
        closedAfterClose,
        recomputeCountAfterExecute};
}

