struct CacheStatsSnapshot {
    size_t graphEntriesBeforeCleanup;
    size_t graphEntriesAfterCleanup;
    double graphHitRatioAfterCleanup;
};

inline CacheStatsSnapshot test_observer_cache_stats() {
    using namespace reaction;

    // 1. Create CacheProbeNode instances
    auto root      = std::make_shared<CacheProbeNode>();
    auto direct1   = std::make_shared<CacheProbeNode>();
    auto direct2   = std::make_shared<CacheProbeNode>();
    auto trans1    = std::make_shared<CacheProbeNode>();
    auto trans2    = std::make_shared<CacheProbeNode>();

    // 2. Get observer graph instance
    auto &graph = ObserverGraph::getInstance();

    // 3. Register nodes
    graph.addNode(root);
    graph.addNode(direct1);
    graph.addNode(direct2);
    graph.addNode(trans1);
    graph.addNode(trans2);

    // 4. Set up direct observer relationship: root -> {direct1, direct2}
    graph.addObserver(direct1, root);
    graph.addObserver(direct2, root);

    // 5. Set up transitive observer relationship:
    //    direct1 -> trans1, direct2 -> trans2
    graph.addObserver(trans1, direct1);
    graph.addObserver(trans2, direct2);

    // 6. Create NodeSet to store collected observers
    NodeSet collectedObservers;

    // 7. Populate cache data: call collectObservers multiple times to create hits.
    graph.collectObservers(root, collectedObservers, 1);
    collectedObservers.clear();
    graph.collectObservers(root, collectedObservers, 1);
    collectedObservers.clear();

    // Small sleep to potentially age entries relative to TTL (not strictly necessary
    // because triggerCleanup also enforces size-based cleanup, but harmless here).
    std::this_thread::sleep_for(std::chrono::milliseconds(10));

    // 8. Get cache statistics before cleanup
    auto statsBefore = graph.getCacheStats();
    size_t graphEntriesBefore = statsBefore.graphStats.totalEntries;

    // 9. Trigger cache cleanup
    graph.triggerCacheCleanup();

    // 10. Get cache statistics after cleanup
    auto statsAfter = graph.getCacheStats();
    size_t graphEntriesAfter = statsAfter.graphStats.totalEntries;
    double hitRatioAfter = statsAfter.graphStats.hitRatio;

    // 11. Close all nodes (remove them from the graph)
    graph.closeNode(root);
    graph.closeNode(direct1);
    graph.closeNode(direct2);
    graph.closeNode(trans1);
    graph.closeNode(trans2);

    // 12. Return cache stats snapshot
    CacheStatsSnapshot snapshot{
        graphEntriesBefore,
        graphEntriesAfter,
        hitRatioAfter,
    };
    return snapshot;
}

}  // namespace test_reaction
