struct ResourceAtomicResult {
    int finalValue;
    bool operationReportedChange;
};

inline ResourceAtomicResult test_resource_atomic(int initialValue, int delta) {
    // 1. Create a Resource instance initialized with the initial value
    reaction::Resource<int> resource(initialValue);

    // 2. Variable to track whether the operation reported a change
    bool operationReportedChange = false;

    // 3. Perform an atomic operation that adds delta to the value
    resource.atomicOperation([&](int &value) {
        int oldValue = value;
        value += delta;
        // Report whether the value actually changed
        operationReportedChange = (value != oldValue);
        return operationReportedChange;
    });

    // 4. Get the final value
    int finalValue = resource.getValue();

    // 5. Return resource atomic result
    return ResourceAtomicResult{finalValue, operationReportedChange};
}

