        GuardName(const GuardName &) = delete;                                  \
        GuardName &operator=(const GuardName &) = delete;                       \
        GuardName(GuardName &&) = delete;                                       \
        GuardName &operator=(GuardName &&) = delete;                            \
                                                                                \
    private:                                                                    \
        Mutex &m_mutex;                                                         \
    }

