template <typename T>
struct ValueWrapper : ExpressionBase<ValueWrapper<T>, std::remove_cvref_t<T>> {
    using value_type = std::remove_cvref_t<T>;

    static_assert(!std::is_reference_v<T>, "ValueWrapper should not store references");

    T m_value;

