inline LogicalExpressionSnapshot test_logical_expression_builders(bool a, bool b, bool c) {
    using namespace reaction;

    // 1. Create reactive boolean variables
    auto ra = var(a);
    auto rb = var(b);
    auto rc = var(c);

    // 2. Build logical AND expression (as an operator expression)
    auto andOp = ra && rb;

    // 3. Build logical OR expression (as an operator expression)
    auto orOp = andOp || rc;

    // Lift operator expressions into reactive calculations
    auto andExpr = expr(andOp);
    auto orExpr  = expr(orOp);

    // 4. Get initial AND and OR results
    LogicalExpressionSnapshot snapshot{};
    snapshot.initialAnd = andExpr().get();
    snapshot.initialOr  = orExpr().get();

    // 5. Update variables to trigger recomputation
    // Flip all three booleans for a visible change
    ra.value(!a);
    rb.value(!b);
    rc.value(!c);

    // 6. Get updated AND and OR results
    snapshot.updatedAnd = andExpr().get();
    snapshot.updatedOr  = orExpr().get();

    // 7. Return logical expression snapshot
    return snapshot;
}

